<template><div class="entries"><article v-for="(value,key) in modelValue" :key="key"><header><strong>{{key}}</strong><button type="button" @click="remove(String(key))">删除条目</button></header><slot :name="'entry'" :entry="value" :entry-key="String(key)" /></article><div class="new"><label>{{ label }}名称<input v-model.trim="newKey" @keydown.enter.prevent="add"></label><button type="button" :disabled="!newKey||newKey in modelValue" @click="add">+ 添加{{label}}</button></div></div></template>
<script setup lang="ts">import{ref}from'vue';const props=defineProps<{modelValue:Record<string,any>;label:string;create:()=>unknown}>();const emit=defineEmits<{'update:modelValue':[value:Record<string,any>]}>();const newKey=ref('');function add(){if(!newKey.value||newKey.value in props.modelValue)return;emit('update:modelValue',{...props.modelValue,[newKey.value]:props.create()});newKey.value=''}function remove(key:string){const next={...props.modelValue};delete next[key];emit('update:modelValue',next)}</script>
<style scoped>.entries{display:grid;gap:10px}.entries article{padding:12px;background:#15181a;border:1px solid #393d3f}.entries header,.new{display:flex;align-items:end;justify-content:space-between;gap:8px}.new label{flex:1}</style>
